import java.lang.*;
import java.util.*;
import java.io.*;

public class Cutting{

    public static int[]strToIntArr(String s){
        String[] sArr = s.split(" ");
        int len = sArr.length;
        int[] retArr = new int[len];
        for(int i=0;i<len;i++){
            retArr[i] = Integer.parseInt(sArr[i]);
        }
        return retArr;
    }

    int getMaxCuts(int n, int b, int[]aArr){
        int len = aArr.length;
        boolean[] valid = new boolean[len];
        int even = 0;
        for(int i=0;i<len;i++){
            if((aArr[i]&1)==0) even++;
            int odd = (i+1)-even;
            if(i>0 && i<len-1 && even==odd){
                valid[i]=true;
            }
        }
        boolean[] used = new boolean[len];
        int nCoins = b;
        int nCuts = 0;
        while(nCoins>0){
            int minCost = nCoins + 1;
            int minInd = -1;
            for(int i=1;i<len-1;i++){
                if(valid[i] && !used[i]){
                    int cost = Math.abs(aArr[i]-aArr[i+1]);
                    if(cost < minCost){
                        minCost = cost;
                        minInd = i;
                    }
                }
            }
            if(minInd==-1) break;
            used[minInd]=true;
            nCoins -= minCost;
            nCuts++;
        }
        return nCuts;
    }

    public static void main(String[]args) throws Exception{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        String nbLn = br.readLine();
        String aLn =  br.readLine();
        int[]nbArr = strToIntArr(nbLn);
        int[]aArr = strToIntArr(aLn);
        Cutting cut = new Cutting();
        int n = nbArr[0];
        int b = nbArr[1];
        int maxC = cut.getMaxCuts(n,b,aArr);
        bw.write(Integer.toString(maxC));
        bw.newLine();
        bw.flush();
    }

}
